import seaborn as sns
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
import matplotlib.gridspec as gridspec

# Set seaborn styling
sns.set(style="darkgrid", palette="colorblind")
colors = sns.color_palette("colorblind")

# Set seed for generating noise
np.random.seed(42)


def sensitivity(estimator, n, k, eta):
    # Note: Binary outcomes are from [0,1] and has smaller sensitivity than outcomes in [-1,1]
    if estimator == 'G-formula':
        deltaeq = 2
        deltaother = 2
    if estimator == 'IPW':
        deltaeq = 2/eta
        deltaother = 1/eta
    if estimator == 'AIPW':
        deltaeq = 2/eta
        deltaother = 1/eta
    return deltaeq/n + deltaother/k # This assumes that k divides n

# Adds noise to non-private ATE estimates
def add_noise(results, sens, mu):
    return [ate + np.random.normal(scale = sens/mu) for ate in results]

def violinplot(data_map, title = "Experiment 1", filename = None):
    labels, data = zip(*data_map.items())

    plt.figure(figsize=(10, 6))

    # Plot data
    ax = sns.violinplot(data=data, inner='box', linewidth=1.2)
    ax.set_xticklabels(labels, fontsize = 14)

    # Add line for true treatment effect
    plt.axhline(0.1, color='black', linestyle='--', label=r'True treatment effect $\tau$')

    # Formatting
    plt.title(title, fontsize=14)
    plt.ylabel("Estimated treatment effect", fontsize=14)
    plt.legend(fontsize = 14)
    plt.tight_layout()
    if filename:
        plt.savefig(filename)
    plt.show()

def violinplots(data_map1, data_map2, title = "Experiment", filename = None):
    labels1, data1 = zip(*data_map1.items())
    labels2, data2 = zip(*data_map2.items())

    fig = plt.figure(figsize=(17, 6))
    gs = gridspec.GridSpec(1, 2, width_ratios=[7, 7])  

    # First plot
    ax1 = fig.add_subplot(gs[0])
    sns.violinplot(data=data1, inner='box', linewidth=1.2, ax=ax1)

    # Set colors and hatches
    styles1 = [
        { 'facecolor':sns.desaturate(colors[0], 0.75)},
        { 'facecolor':sns.desaturate(colors[1], 0.75)},
        { 'facecolor':sns.desaturate(colors[7], 0.75)},
        { 'facecolor':sns.desaturate(colors[4], 0.75)},
        { 'facecolor':sns.desaturate(colors[3], 0.75)},
        { 'facecolor':sns.desaturate(colors[3], 0.75), "hatch": ".."},
        { 'facecolor':sns.desaturate(colors[2], 0.75)},
              ]
    for violin, style in zip(ax1.collections, styles1):
        violin.set(**style)

    # Add line and text between prior methods and us
    split_pos = 2.5
    ax1.axvline(x=split_pos, color="black", linewidth=1)
    ymin, ymax = ax1.get_ylim()
    ax1.text(2.45, ymin + (ymax-ymin)*0.04, "Prior methods", ha="right", va="bottom", fontsize=18, fontweight="bold")
    ax1.text(0.87, ymin + (ymax-ymin)*0.04, r"$\longleftarrow$", ha="right", va="bottom", fontsize=18, fontweight="bold")
    ax1.text(2.55, ymin + (ymax-ymin)*0.04, "Our Techniques", ha="left", va="bottom", fontsize=18, fontweight="bold")
    ax1.text(4.3, ymin + (ymax-ymin)*0.04, r"$\longrightarrow$", ha="left", va="bottom", fontsize=18, fontweight="bold")

    ax1.set_xticklabels(labels1, fontsize=18)
    ax1.axhline(0.10, color='black', linestyle='--', label=r'True treatment effect $\tau$')
    ax1.set_ylabel("Estimated treatment effect", fontsize=20)
    ax1.legend(fontsize=16)
    plt.yticks(fontsize=16)
    ax1.set_title(r"Privacy parameters: $1.5-$GDP and $7.05-$DP", fontsize=14)

    # Second plot
    ax2 = fig.add_subplot(gs[1])
    sns.violinplot(data=data2, inner='box', linewidth=1.2, ax=ax2)

    # Set colors and hatches
    styles2 = [
        { 'facecolor':sns.desaturate(colors[0], 0.75)},
        { 'facecolor':sns.desaturate(colors[1], 0.75)},
        { 'facecolor':sns.desaturate(colors[7], 0.75)},
        { 'facecolor':sns.desaturate(colors[4], 0.75)},
        { 'facecolor':sns.desaturate(colors[3], 0.75)},
        { 'facecolor':sns.desaturate(colors[3], 0.75), "hatch": ".."},
        { 'facecolor':sns.desaturate(colors[2], 0.75)},
              ]
    for violin, style in zip(ax2.collections, styles2):
        violin.set(**style)

    # Add line and text between prior methods and us
    split_pos = 2.5
    ax2.axvline(x=split_pos, color="black", linewidth=1)
    ymin, ymax = ax2.get_ylim()
    ax2.text(2.45, ymin + (ymax-ymin)*0.04, "Prior methods", ha="right", va="bottom", fontsize=18, fontweight="bold")
    ax2.text(0.87, ymin + (ymax-ymin)*0.04, r"$\longleftarrow$", ha="right", va="bottom", fontsize=18, fontweight="bold")
    ax2.text(2.55, ymin + (ymax-ymin)*0.04, "Our Techniques", ha="left", va="bottom", fontsize=18, fontweight="bold")
    ax2.text(4.3, ymin + (ymax-ymin)*0.04, r"$\longrightarrow$", ha="left", va="bottom", fontsize=18, fontweight="bold")

    ax2.set_xticklabels(labels2, fontsize=18)
    ax2.axhline(0.10, color='black', linestyle='--', label=r'True treatment effect $\tau$')
    ax2.legend(fontsize=16)
    plt.yticks(fontsize=16)
    ax2.set_title(r"Privacy parameters: $0.5-$GDP and $2-$DP", fontsize=14)

    plt.tight_layout()
    if filename:
        plt.savefig(filename)
    plt.show()


